import re
import datetime
import json

def extract(text: str) -> dict:
    t = text.strip()
    s = re.sub(r'\s+', ' ', t.lower())

    appt_words = r'(?:appointment|appointments|appt|appts|meeting|meetings|doctor|doctors|visit|visits|checkup|check-up|consultation|consultations|schedule|scheduled)'
    intent_patterns = [
        rf'\b(?:any|what|which|show|list|do i have|are there)?\s*{appt_words}\b',
        rf'\b{appt_words}\s+(?:coming up|upcoming|this|next|between|from|in|since|for|within|over)\b',
        rf'\bcoming up\b.*\b{appt_words}\b',
        rf'\bupcoming\b.*\b{appt_words}\b',
        rf'\bmeetings? i should be aware of\b',
    ]
    if not any(re.search(p, s, re.I) for p in intent_patterns):
        raise ValueError('not appointments')

    month = r'(?:january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)'
    iso = r'\d{4}-\d{2}-\d{2}'
    day_month = rf'\d{{1,2}}(?:st|nd|rd|th)?\s+{month}(?:\s+\d{{4}})?'
    month_day = rf'{month}\s+\d{{1,2}}(?:st|nd|rd|th)?(?:,?\s*\d{{4}})?'
    date_phrase = rf'(?:{iso}|{day_month}|{month_day}|{month})'

    m = re.search(rf'\bbetween\s+({date_phrase})\s+and\s+({date_phrase})\b', s, re.I)
    if m:
        return {"intent": "appointments", "period": "range", "start": m.group(1).strip(), "end": m.group(2).strip()}

    m = re.search(rf'\bfrom\s+({date_phrase})\s+to\s+({date_phrase})\b', s, re.I)
    if m:
        return {"intent": "appointments", "period": "range", "start": m.group(1).strip(), "end": m.group(2).strip()}

    m = re.search(rf'\bin\s+({month}|{iso})\b', s, re.I)
    if m:
        v = m.group(1).strip()
        return {"intent": "appointments", "period": "range", "start": v, "end": v}

    m = re.search(rf'\bsince\s+({date_phrase})\b', s, re.I)
    if m:
        return {"intent": "appointments", "period": "range", "start": m.group(1).strip()}

    if re.search(r'\bthis month\b', s, re.I):
        return {"intent": "appointments", "period": "this_month"}
    if re.search(r'\bthis week\b', s, re.I):
        return {"intent": "appointments", "period": "this_week"}
    if re.search(r'\bnext month\b', s, re.I):
        return {"intent": "appointments", "period": "next_month"}
    if re.search(r'\b(?:next\s+7\s+days|next\s+week|within\s+7\s+days)\b', s, re.I):
        return {"intent": "appointments", "period": "next_7_days"}
    if re.search(r'\b(?:next\s+14\s+days|next\s+two\s+weeks|next\s+2\s+weeks|two\s+weeks|14\s+days)\b', s, re.I):
        return {"intent": "appointments", "period": "next_14_days"}
    if re.search(r'\b(?:next\s+30\s+days|30\s+days)\b', s, re.I):
        return {"intent": "appointments", "period": "next_30_days"}
    if re.search(r'\b(?:last\s+month|past\s+30\s+days|last\s+30\s+days)\b', s, re.I):
        return {"intent": "appointments", "period": "last_30_days"}
    if re.search(r'\b(?:all\s+(?:appointments|meetings|doctors|visits)|every\s+(?:appointment|meeting|visit))\b', s, re.I):
        return {"intent": "appointments", "period": "all"}

    return {"intent": "appointments", "period": "upcoming"}
